import React, { useState, useEffect } from 'react';

const Hero = () => {
  const [displayText, setDisplayText] = useState('');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [introText, setIntroText] = useState('');
  const [introIndex, setIntroIndex] = useState(0);
  const [showButton, setShowButton] = useState(false);

  const fullText = "Hi, I'm An.";
  const fullIntroText = "From auditing numbers to building software,\nI've always loved exploring different paths and perspectives.\nI'm driven to turn these experiences into skills that create real impact in the world";

  // 打字效果 - 名字和介紹文字連續進行
  useEffect(() => {
    const timer = setTimeout(() => {
      if (currentIndex < fullText.length) {
        // 先打完名字
        setDisplayText(prev => prev + fullText[currentIndex]);
        setCurrentIndex(prev => prev + 1);
      } else if (introIndex < fullIntroText.length) {
        // 名字完成後，繼續打介紹文字
        setIntroText(prev => prev + fullIntroText[introIndex]);
        setIntroIndex(prev => prev + 1);
      } else {
        // 所有文字完成後，顯示按鈕
        setTimeout(() => {
          setShowButton(true);
        }, 1000);
      }
    }, currentIndex < fullText.length ? 150 : 50);

    return () => clearTimeout(timer);
  }, [currentIndex, fullText.length, introIndex, fullIntroText.length]);

  const handleButtonClick = () => {
    // 可以添加其他功能，比如顯示更多信息或重新開始動畫
    console.log('Button clicked!');
  };

  return (
    <section id="hero" className="min-h-screen flex items-center justify-center bg-gray-900 relative overflow-hidden">
      {/* 背景效果 */}
      <div className="absolute inset-0">
        <div className="absolute top-1/4 left-1/4 w-72 h-72 bg-green-500 rounded-full mix-blend-multiply filter blur-xl opacity-10"></div>
        <div className="absolute top-3/4 right-1/4 w-72 h-72 bg-green-400 rounded-full mix-blend-multiply filter blur-xl opacity-10"></div>
        <div className="absolute bottom-1/4 left-1/3 w-72 h-72 bg-green-600 rounded-full mix-blend-multiply filter blur-xl opacity-10"></div>
      </div>

      <div className="relative z-10 text-left text-green-400 px-6 max-w-4xl mx-auto">
        {/* 打字效果文字 */}
        <div className="mb-8">
          <h1 className="text-5xl md:text-7xl font-bold mb-4">
            <span className="inline-block">
              {displayText}
              {currentIndex < fullText.length && <span className="animate-pulse text-green-300">|</span>}
            </span>
          </h1>
        </div>

        {/* 介紹文字 - 打字效果 */}
        {currentIndex === fullText.length && (
          <div className="mb-8 text-left">
            <div className="text-xl md:text-2xl text-green-300 leading-relaxed max-w-4xl mx-auto">
              <div className="whitespace-pre-line">
                {introText}
                {introIndex < fullIntroText.length && <span className="animate-pulse text-green-400">|</span>}
              </div>
            </div>
          </div>
        )}

        {/* 開始按鈕 - 上升效果 */}
        {showButton && (
          <div className="animate-fade-in-up">
            <button 
              className="group relative inline-flex items-center justify-center px-8 py-4 text-lg font-semibold text-gray-900 bg-gradient-to-r from-green-400 to-green-600 rounded-full hover:from-green-500 hover:to-green-700 transform hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl"
              onClick={handleButtonClick}
            >
              <span className="relative z-10 flex items-center">
                Get to know me
                <svg className="ml-2 w-5 h-5 group-hover:translate-x-1 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                </svg>
              </span>
              <div className="absolute inset-0 bg-gradient-to-r from-green-500 to-green-700 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            </button>
          </div>
        )}
      </div>

      {/* 滾動指示器 */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 animate-bounce">
        <div className="w-6 h-10 border-2 border-green-400/30 rounded-full flex justify-center">
          <div className="w-1 h-3 bg-green-400/50 rounded-full mt-2 animate-pulse"></div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
